32	
33	  /// Whether or not a LLDB process is running.
34	  bool get isRunning => _lldbProcess != null;
35	
36	  /// Whether or not the LLDB process has attached and resumed the application process.
37	  var _isAttached = false;
38	
39	  /// The process id of the application running on the iOS device.
40	  int? get appProcessId => _lldbProcess?.appProcessId;
41	
42	  _LLDBLogPatternCompleter? _logCompleter;
43	
44	  /// Pattern of lldb log when the process is stopped.
45	  ///
46	  /// Example: (lldb) Process 6152 stopped
47	  static final _lldbProcessStopped = RegExp(r'Process \d* stopped');
48	
49	  /// Pattern of lldb log when the process is resuming.
50	  ///
51	  /// Example: (lldb) Process 6152 resuming
52	  static final _lldbProcessResuming = RegExp(r'Process \d+ resuming');
53	
54	  /// Pattern of lldb log when the breakpoint is added.
55	  ///
56	  /// Example: Breakpoint 1: no locations (pending).
57	  static final _breakpointPattern = RegExp(r'Breakpoint (\d+)*:');
58	
59	  /// A list of log patterns to ignore.
60	  static final _ignorePatterns = <Pattern>[RegExp(r'\d+ location added to breakpoint \d+')];
61	
62	  /// Breakpoint script required for JIT on iOS.
63	  ///
64	  /// This should match the "handle_new_rx_page" function in [IosProject._lldbPythonHelperTemplate].
65	  static const _pythonScript = '''
66	"""Intercept NOTIFY_DEBUGGER_ABOUT_RX_PAGES and touch the pages."""
67	base = frame.register["x0"].GetValueAsAddress()
68	page_len = frame.register["x1"].GetValueAsUnsigned()
69	
70	# Note: NOTIFY_DEBUGGER_ABOUT_RX_PAGES will check contents of the
71	# first page to see if handled it correctly. This makes diagnosing
72	# misconfiguration (e.g. missing breakpoint) easier.
73	data = bytearray(page_len)
74	data[0:8] = b'IHELPED!'
75	
76	error = lldb.SBError()
77	frame.GetThread().GetProcess().WriteMemory(base, data, error)
78	if not error.Success():
79	    print(f'Failed to write into {base}[+{page_len}]', error)
80	    return
81	''';
