83	  /// Starts an LLDB process and inputs commands to start debugging the [appProcessId].
84	  /// This will start a debugserver on the device, which is required for JIT.
85	  ///
86	  /// After attaching and starting the app process, forwards logs to [lldbLogForwarder].
87	  /// This may include crash logs.
88	  Future<bool> attachAndStart({
89	    required String deviceId,
90	    required int appProcessId,
91	    required LLDBLogForwarder lldbLogForwarder,
92	  }) async {
93	    Timer? timer;
94	    try {
95	      timer = Timer(const Duration(minutes: 1), () {
96	        _logger.printError(
97	          'LLDB is taking longer than expected to start debugging the app. '
98	          "LLDB debugging can be disabled for the project by adding the following in the project's pubspec.yaml:\n"
99	          'flutter:\n'
100	          '  config:\n'
101	          '    enable-lldb-debugging: false\n'
102	          'Or disable LLDB debugging globally with the following command:\n'
103	          '  "flutter config --no-enable-lldb-debugging"',
104	        );
105	      });
106	
107	      final bool start = await _startLLDB(
108	        appProcessId: appProcessId,
109	        lldbLogForwarder: lldbLogForwarder,
110	      );
111	      if (!start) {
112	        return false;
113	      }
114	      await _selectDevice(deviceId);
115	      await _setBreakpoint();
116	      await _attachToAppProcess(appProcessId);
117	      await _resumeProcess();
118	      _isAttached = true;
119	    } on _LLDBError catch (e) {
120	      _logger.printTrace('lldb failed with error: ${e.message}');
121	      exit();
122	      return false;
123	    } finally {
124	      timer?.cancel();
125	    }
126	    return true;
127	  }
