61	  /// Install and launch the app on the device with `devicectl` ([_coreDeviceControl])
62	  /// and do not attach a debugger. This is generally only used for release mode.
63	  Future<bool> launchAppWithoutDebugger({
64	    required String deviceId,
65	    required String bundlePath,
66	    required String bundleId,
67	    required List<String> launchArguments,
68	  }) async {
69	    // Install app to device
70	    final (bool installStatus, IOSCoreDeviceInstallResult? installResult) = await _coreDeviceControl
